// Mira Knowledge Base: embedded project data + deterministic FACTS.
// Code computes counts, filters and dates so the LLM agents never have to.
// To use another project, replace the four data blocks below.

const cfg = $('Config').first().json;

// ---------- Embedded project data (generated from Resources/) ----------
const PROJECT_NAME = 'AI Adoption Project – ABCDE Ltd.';
const PROJECT_DESCRIPTION = `AI Adoption Project Description for ABCDE Ltd.

ABCDE Ltd., a mid-sized enterprise specializing in logistics and supply chain solutions, is embarking on an AI adoption initiative to enhance operational efficiency, improve customer experience, and drive data-driven decision-making across the organization. This project will focus on integrating AI-powered tools into core business functions, including demand forecasting, route optimization, inventory management, and customer support. By leveraging machine learning models and natural language processing, the company aims to reduce manual overhead, minimize errors, and uncover actionable insights from historical and real-time data.

The AI adoption project will be implemented in phases, beginning with a detailed assessment of current workflows and data infrastructure, followed by pilot implementations in targeted departments. Key goals include reducing delivery delays by 15%, lowering operational costs by 10%, and improving service responsiveness. A cross-functional task force comprising data scientists, IT professionals, and business stakeholders will oversee the deployment and ensure alignment with organizational objectives. This strategic move is expected to position ABCDE Ltd. as a technology-forward leader in the logistics industry.`;
const TIMELINE_CSV = `phase,phase_name,start_week,end_week,key_activities,milestones_deliverables
1,Project Initiation,1,2,"Define project scope; Form cross-functional team; Initial stakeholder meeting","Project charter signed off; Team structure finalized"
2,Current State Analysis,3,4,"Assess existing processes & systems; Identify data sources & gaps","Current systems audit report; Gap analysis report"
3,Use Case Selection,5,6,"Shortlist priority AI use cases (forecasting, route optimization)","Final list of prioritized use cases with success criteria"
4,Pilot Design,7,10,"Data collection & preparation; Model design and development","Working prototype models; Data pipelines established"
5,Pilot Implementation,11,14,"Deploy AI models in test environments; Monitor performance","Pilot results report; User feedback and performance metrics"
6,Evaluation & Iteration,15,16,"Evaluate pilot outcomes; Adjust models as needed","Updated models and process refinements"
7,Full Deployment,17,22,"Scale AI models across selected departments; Train staff","Full production rollout; Training sessions completed"
8,Monitoring & Review,23,24,"Continuous performance monitoring; Final project review","Project closure report; Recommendations for future scaling"`;
const RISKS_CSV = `risk_id,category,risk_challenge,impact,mitigation_strategy
R01,Data Quality & Availability,Incomplete or unstructured data,Poor model performance and inaccurate outcomes,Perform early data audits and implement robust data governance
R02,Integration Issues,Difficulty integrating AI with legacy systems,Delays in deployment and operational disruptions,Plan integration roadmap and use APIs/middleware
R03,Talent & Skills Gap,Lack of internal AI/ML expertise,Overreliance on external vendors and slow progress,Provide staff training and hire specialized talent
R04,Change Resistance,Employees resist adopting AI-driven workflows,Low adoption and reduced ROI,Strong change management and early engagement
R05,Ethical & Legal Concerns,Risks of biased models or data privacy violations,Legal repercussions and reputational damage,Involve legal early and implement fairness checks
R06,Cost Overruns,Underestimation of AI development costs,Budget constraints and project delays,Set realistic budget and build in contingency funds
R07,Unrealistic Expectations,Stakeholders expect immediate ROI,Disillusionment and loss of support,Align expectations and show quick wins
R08,Model Performance Drift,AI models lose accuracy over time,Incorrect decisions and trust erosion,Regular retraining cycles and monitoring dashboards
R09,Security Vulnerabilities,AI models targeted by adversarial attacks,Data breaches and operational risks,Adopt AI security best practices and penetration testing
R10,Vendor Lock-in,Overdependence on a specific AI platform,Flexibility loss and future switching costs,Favor open standards and negotiate flexible vendor terms`;
const TASKS_CSV = `task_id,task_name,status,assignee,priority,sprint,due_date,labels,description
T001,Define project scope and objectives,Done,Arjun Mehta,High,Sprint 1,2026-04-07,Planning,"Document project scope, goals, and success criteria for AI adoption"
T002,Form cross-functional task force,Done,Sarah Lin,High,Sprint 1,2026-04-07,Planning,"Identify and onboard team members from data science, IT, and business units"
T003,Initial stakeholder alignment meeting,Done,Arjun Mehta,High,Sprint 1,2026-04-10,Planning,"Present project charter and get sign-off from leadership"
T004,Audit existing data infrastructure,Done,Priya Nair,High,Sprint 2,2026-04-18,Analysis,"Assess current databases, data pipelines, and data quality"
T005,Map current logistics workflows,Done,James Wong,Medium,Sprint 2,2026-04-18,Analysis,"Document end-to-end processes for demand forecasting, routing, and inventory"
T006,Identify data gaps and quality issues,In Progress,Priya Nair,High,Sprint 2,2026-04-21,Analysis,"Gap analysis report comparing available data vs requirements for AI models"
T007,Shortlist AI use cases,In Progress,Arjun Mehta,High,Sprint 3,2026-04-28,Use Cases,"Evaluate and prioritize: demand forecasting, route optimization, inventory mgmt, customer support"
T008,Define success criteria for each use case,To Do,Sarah Lin,High,Sprint 3,2026-05-02,Use Cases,"Set measurable KPIs: 15% reduction in delivery delays, 10% cost reduction"
T009,Vendor evaluation for ML platform,To Do,James Wong,Medium,Sprint 3,2026-05-05,Use Cases,"Compare cloud ML platforms (AWS SageMaker, Azure ML, GCP Vertex AI)"
T010,Collect historical demand data,To Do,Priya Nair,High,Sprint 4,2026-05-12,Data Prep,"Extract 2 years of demand data from ERP system"
T011,Data cleaning and preprocessing pipeline,To Do,Priya Nair,High,Sprint 4,2026-05-19,Data Prep,"Build automated pipeline for data cleaning, normalization, feature engineering"
T012,Design demand forecasting model,To Do,Ravi Kumar,High,Sprint 4,2026-05-19,Model Dev,"Select algorithm (LSTM, Prophet, XGBoost), define input features"
T013,Design route optimization model,To Do,Ravi Kumar,Medium,Sprint 5,2026-05-26,Model Dev,"Graph-based optimization with constraints (time windows, vehicle capacity)"
T014,Build model training pipeline,To Do,Ravi Kumar,High,Sprint 5,2026-06-02,Model Dev,"Automated training, validation, and model versioning"
T015,Deploy demand model to test environment,To Do,James Wong,High,Sprint 6,2026-06-09,Pilot,"Deploy to staging, set up monitoring, define test scenarios"
T016,Run pilot with logistics team,To Do,Arjun Mehta,High,Sprint 6,2026-06-16,Pilot,"2-week pilot with 3 logistics coordinators using demand forecasting predictions"
T017,Collect pilot feedback and metrics,To Do,Sarah Lin,High,Sprint 7,2026-06-23,Evaluation,"Survey users, measure prediction accuracy, compare with manual forecasts"
T018,Iterate on model based on feedback,To Do,Ravi Kumar,Medium,Sprint 7,2026-06-30,Evaluation,"Adjust features, retrain model, validate improvements"
T019,Prepare production deployment plan,To Do,James Wong,High,Sprint 8,2026-07-07,Deployment,"Infrastructure scaling, rollback plan, monitoring setup"
T020,Staff training program,To Do,Sarah Lin,Medium,Sprint 8,2026-07-14,Deployment,"Train 25 logistics staff on using AI-powered forecasting dashboard"
T021,Full production rollout,To Do,Arjun Mehta,High,Sprint 9,2026-07-21,Deployment,"Go-live for demand forecasting across all 3 distribution centers"
T022,Set up continuous monitoring,To Do,Priya Nair,High,Sprint 9,2026-07-28,Monitoring,"Model performance dashboards, drift detection alerts, retraining triggers"
T023,Project closure report,To Do,Arjun Mehta,Medium,Sprint 10,2026-08-04,Monitoring,"Final report: outcomes vs targets, lessons learned, recommendations for Phase 2"
T024,Security review of AI infrastructure,Blocked,James Wong,High,Sprint 5,2026-05-26,Security,"Penetration testing and vulnerability assessment - BLOCKED: waiting for security team availability"
T025,Legal review of data usage,In Progress,Sarah Lin,High,Sprint 3,2026-04-28,Compliance,"Review data privacy compliance for using customer delivery data in ML models"`;

// ---------- Helpers ----------
function parseCsv(text) {
  const rows = [];
  let row = [], field = '', inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"' && text[i + 1] === '"') { field += '"'; i++; }
      else if (c === '"') inQuotes = false;
      else field += c;
    } else if (c === '"') inQuotes = true;
    else if (c === ',') { row.push(field); field = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++;
      row.push(field); field = '';
      if (row.some((v) => v.trim() !== '')) rows.push(row);
      row = [];
    } else field += c;
  }
  row.push(field);
  if (row.some((v) => v.trim() !== '')) rows.push(row);
  const [header, ...body] = rows;
  return body.map((r) => Object.fromEntries(header.map((h, i) => [h.trim(), (r[i] ?? '').trim()])));
}

const DAY = 86400000;
const toDate = (s) => { const [y, m, d] = s.split('-').map(Number); return new Date(Date.UTC(y, m - 1, d)); };
const fmt = (d) => d.toISOString().slice(0, 10);
const addDays = (d, n) => new Date(d.getTime() + n * DAY);
const daysBetween = (a, b) => Math.round((b - a) / DAY);
const countBy = (arr, key) => arr.reduce((acc, x) => ({ ...acc, [x[key]]: (acc[x[key]] ?? 0) + 1 }), {});

const asOf = toDate(cfg.asOfDate);
const projectStart = toDate(cfg.projectStartDate);
const upcomingEnd = addDays(asOf, Number(cfg.upcomingWindowDays));
const dueSoonEnd = addDays(asOf, Number(cfg.dueSoonDays));
const STATUSES = ['Done', 'In Progress', 'Blocked', 'To Do'];

// ---------- Timeline: week numbers -> calendar dates ----------
const timeline = parseCsv(TIMELINE_CSV).map((p) => {
  const start = addDays(projectStart, (Number(p.start_week) - 1) * 7);
  const end = addDays(projectStart, Number(p.end_week) * 7 - 1);
  const status = end < asOf ? 'Completed (by schedule)' : start > asOf ? 'Upcoming' : 'Current';
  return {
    phase: Number(p.phase),
    phase_name: p.phase_name,
    start_week: Number(p.start_week),
    end_week: Number(p.end_week),
    start_date: fmt(start),
    end_date: fmt(end),
    schedule_status: status,
    key_activities: p.key_activities.split(';').map((s) => s.trim()).filter(Boolean),
    milestones: p.milestones_deliverables.split(';').map((s) => s.trim()).filter(Boolean),
  };
});

// Each milestone is due at the end of its phase.
const milestones = timeline.flatMap((p) => p.milestones.map((m) => ({
  milestone: m,
  phase: p.phase,
  phase_name: p.phase_name,
  due_week: p.end_week,
  due_date: p.end_date,
  days_from_as_of: daysBetween(asOf, toDate(p.end_date)),
})));

// ---------- Project outcome phrases ----------
// Short verbatim phrases from the description (goals, use cases, capabilities). Agents cite these
// from a fixed list instead of free-text quoting, so a citation can never be invented.
const LEAD = /^(and|or|including|include|includes|the company aims to|aims to|by leveraging|by|to|of|with|is embarking on an ai adoption initiative to|key goals include|this project will focus on|beginning with|followed by|will)\s+/i;
const outcomePhrases = [...new Set(PROJECT_DESCRIPTION.split('\n').slice(1).join(' ')
  .split(/[.;,]|\s+and\s+(?=[a-z]+ing\b|improv|reduc|lower|minim|uncov|drive|enhanc)/)
  .map((s) => { let t = s.trim(), prev; do { prev = t; t = t.replace(LEAD, ''); } while (t !== prev); return t; })
  .filter((s) => { const n = s.split(/\s+/).length; return n >= 2 && n <= 9 && !/ABCDE|^This|^The /.test(s); }))];
const USE_CASES = ['demand forecasting', 'route optimization', 'inventory management', 'customer support']
  .filter((u) => PROJECT_DESCRIPTION.toLowerCase().includes(u));

// ---------- Risks ----------
const risks = parseCsv(RISKS_CSV);

// ---------- Tasks ----------
const tasks = parseCsv(TASKS_CSV).map((t) => {
  const due = toDate(t.due_date);
  return { ...t, days_until_due: daysBetween(asOf, due) };
});
const open = (t) => t.status !== 'Done';

const statusCounts = Object.fromEntries(STATUSES.map((s) => [s, tasks.filter((t) => t.status === s).length]));
const unknownStatuses = tasks.filter((t) => !STATUSES.includes(t.status)).map((t) => `${t.task_id}: ${t.status}`);

const sprintNames = [...new Set(tasks.map((t) => t.sprint))]
  .sort((a, b) => Number(a.replace(/\D/g, '')) - Number(b.replace(/\D/g, '')));
const sprints = sprintNames.map((name) => {
  const ts = tasks.filter((t) => t.sprint === name);
  const dues = ts.map((t) => t.due_date).sort();
  return {
    sprint: name,
    first_due: dues[0],
    last_due: dues[dues.length - 1],
    task_count: ts.length,
    status_counts: Object.fromEntries(STATUSES.map((s) => [s, ts.filter((t) => t.status === s).length])),
    task_ids: ts.map((t) => t.task_id),
  };
});
// Current sprint = first sprint whose last due date has not passed.
const currentSprint = (sprints.find((s) => toDate(s.last_due) >= asOf) ?? sprints[sprints.length - 1]).sprint;

const brief = (t) => ({
  task_id: t.task_id, task_name: t.task_name, status: t.status, assignee: t.assignee,
  priority: t.priority, sprint: t.sprint, due_date: t.due_date, days_until_due: t.days_until_due,
});

const blocked = tasks.filter((t) => t.status === 'Blocked').map((t) => ({ ...brief(t), description: t.description }));
const overdue = tasks.filter((t) => open(t) && toDate(t.due_date) < asOf).map(brief);
const dueSoon = tasks.filter((t) => open(t) && t.status !== 'Blocked'
  && toDate(t.due_date) >= asOf && toDate(t.due_date) <= dueSoonEnd).map(brief);

const workload = Object.entries(countBy(tasks.filter(open), 'assignee'))
  .map(([assignee, open_tasks]) => ({
    assignee,
    open_tasks,
    open_high_priority: tasks.filter((t) => open(t) && t.assignee === assignee && t.priority === 'High').length,
    in_progress: tasks.filter((t) => t.status === 'In Progress' && t.assignee === assignee).map((t) => t.task_id),
  }))
  .sort((a, b) => b.open_tasks - a.open_tasks);

const currentWeek = Math.floor(daysBetween(projectStart, asOf) / 7) + 1;
const currentPhase = timeline.find((p) => p.schedule_status === 'Current') ?? null;

const facts = {
  as_of_date: fmt(asOf),
  project_start_date: fmt(projectStart),
  current_week: currentWeek,
  total_weeks: Math.max(...timeline.map((p) => p.end_week)),
  current_phase: currentPhase ? `Phase ${currentPhase.phase}: ${currentPhase.phase_name}` : 'None (outside timeline)',
  current_sprint: currentSprint,
  total_tasks: tasks.length,
  status_counts: statusCounts,
  completion_pct: Math.round((statusCounts.Done / tasks.length) * 100),
  blocked_tasks: blocked,
  overdue_tasks: overdue,
  due_soon_tasks: dueSoon,
  due_soon_window: `${fmt(asOf)} to ${fmt(dueSoonEnd)}`,
  upcoming_milestones: milestones.filter((m) => m.days_from_as_of >= 0 && toDate(m.due_date) <= upcomingEnd),
  upcoming_window: `${fmt(asOf)} to ${fmt(upcomingEnd)}`,
  next_milestones_after_window: milestones.filter((m) => toDate(m.due_date) > upcomingEnd).slice(0, 2),
  sprints,
  workload,
  risk_count: risks.length,
  risk_categories: risks.map((r) => `${r.risk_id} ${r.category}`),
  data_warnings: unknownStatuses.map((s) => `Unrecognised task status: ${s}`),
};

return [{
  json: {
    project: { name: PROJECT_NAME, description: PROJECT_DESCRIPTION.trim(), outcome_phrases: outcomePhrases, use_cases: USE_CASES },
    timeline,
    milestones,
    risks,
    tasks,
    facts,
  },
}];

// Scores each agent output against its test's expectations (see Test Cases node).

const outputs = $input.all().map((i) => i.json);
const traceIds = outputs.map((o) => o.langsmith_trace_id);

function evaluate(check, out) {
  const text = out.markdown.toLowerCase();
  switch (check.type) {
    case 'status':
      return [[].concat(check.value).includes(out.status), `status ${out.status}`];
    case 'phase_count':
      return [out.phase_count === check.value, `${out.phase_count} phases`];
    case 'field':
      return [out[check.field] === check.value, `${check.field} = ${JSON.stringify(out[check.field])}`];
    case 'grounded_min': {
      const score = out.grounding?.score ?? 0;
      return [score >= check.value, `groundedness ${(score * 100).toFixed(0)}%`];
    }
    case 'mentions_all': {
      const missing = check.value.filter((term) => !text.includes(term.toLowerCase()));
      return [missing.length === 0, missing.length ? `missing: ${missing.join(', ')}` : `mentions ${check.value.join(', ')}`];
    }
    case 'mentions_any': {
      const hit = check.value.filter((term) => text.includes(term.toLowerCase()));
      return [hit.length > 0, hit.length ? `mentions ${hit.join(', ')}` : `none of: ${check.value.join(', ')}`];
    }
    case 'not_mentions': {
      const found = check.value.filter((term) => text.includes(term.toLowerCase()));
      return [found.length === 0, found.length ? `should not mention: ${found.join(', ')}` : 'no forbidden terms'];
    }
    default:
      return [false, `unknown check ${check.type}`];
  }
}

return outputs.map((out, i) => {
  const results = (out.checks ?? []).map((c) => {
    const [pass, detail] = evaluate(c, out);
    return `${pass ? 'PASS' : 'FAIL'} – ${c.type}: ${detail}`;
  });
  const failed = results.filter((r) => r.startsWith('FAIL')).length;
  return {
    json: {
      test_id: out.test_id,
      verdict: results.length === 0 ? 'NO CHECKS' : failed === 0 ? 'PASS' : 'FAIL',
      checks: results,
      status: out.status,
      tokens: out.usage.total_tokens,
      route: out.route,
      langsmith_trace_id: traceIds[i],
      response: out.markdown,
      output: out.markdown, // shown as the reply when Mira runs from the Chat Trigger
    },
  };
});

// Orchestrator – classifies the request (intent) and decides whether it is about the project on file.
// It never answers the request; routing and the insufficiency gate are applied in code afterwards.

const cfg = $('Config').first().json;
const kb = $('Knowledge Base').first().json;

const SYSTEM_PROMPT = `ROLE
You are the Orchestrator of Mira, a project intelligence assistant for PMs/TPMs at Nexora. You classify each request so it can be routed to the right specialist agent. You never answer the request yourself.

PROJECT ON FILE
Mira has exactly one project on file: "${kb.project.name}" – project description, ${kb.timeline.length}-phase timeline, risk register (${kb.risks[0].risk_id}–${kb.risks[kb.risks.length - 1].risk_id}) and task board (${kb.tasks.length} tasks, ${kb.facts.sprints.length} sprints).

FIELDS
- intent:
  plan – project plan, roadmap, phases, schedule outline
  risk – risk assessment, top risks, risk analysis
  status – status report, progress summary, task counts, sprint report
  milestone – upcoming milestones or deadlines, blocked / overdue / at-risk tasks, schedule alerts
  comms – stakeholder update, email, announcement, newsletter
  out_of_scope – anything else
- uses_project_on_file: true when the request is about the project on file – it names ABCDE or the AI Adoption Project, or refers to "the project", "the task board", "the risk data", "the timeline", "Sprint N", "milestones" without describing a different project. false when the request supplies its own project or content (e.g. quoted text after "for:"), talks about "a new project" or "a 2-week project", or is otherwise not about the project on file.
- request_details_sufficient: judge ONLY the request text. true only if it explicitly states the objective AND the scope or deliverables AND a timeline or team size. A one-line idea or a duration alone is not sufficient.
- sprint: the sprint number if one is explicitly mentioned, else null.
- window_days: the look-ahead window in days if one is stated ("next 2 weeks" → 14, "this month" → 30), else null.
- reason: one sentence explaining the classification.

EXAMPLES
"Draft a roadmap for ABCDE's AI rollout" → plan, uses_project_on_file true
'Create a plan for: "Launch a mobile app."' → plan, false, request_details_sufficient false
"Plan a 6-week data-warehouse migration for finance with 4 engineers, delivering a cloud warehouse and 12 migrated reports" → plan, false, true
"Risk analysis for a new CRM migration" → risk, false, false
'Give me a status update: "All good this week."' → status, false, false
"What deadlines are coming up in the next 10 days?" → milestone, true, window_days 10
"Write an email to leadership about Sprint 4" → comms, true, sprint 4
"What's the capital of France?" → out_of_scope, false

OUTPUT
Return JSON matching the provided schema.`;

const RESPONSE_FORMAT = {
  type: 'json_schema',
  json_schema: {
    name: 'orchestrator_decision',
    strict: true,
    schema: {
      type: 'object', additionalProperties: false,
      required: ['intent', 'uses_project_on_file', 'request_details_sufficient', 'sprint', 'window_days', 'reason'],
      properties: {
        intent: { type: 'string', enum: ['plan', 'risk', 'status', 'milestone', 'comms', 'out_of_scope'] },
        uses_project_on_file: { type: 'boolean' },
        request_details_sufficient: { type: 'boolean' },
        sprint: { anyOf: [{ type: 'null' }, { type: 'integer' }] },
        window_days: { anyOf: [{ type: 'null' }, { type: 'integer' }] },
        reason: { type: 'string' },
      },
    },
  },
};

return $input.all().map(({ json: req }) => ({
  json: {
    ...req,
    orchestrator_started_at: new Date().toISOString(),
    openaiRequest: {
      model: cfg.model,
      temperature: 0,
      max_tokens: 400,
      response_format: RESPONSE_FORMAT,
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user', content: `USER REQUEST:\n${req.query}` },
      ],
    },
  },
}));

// Orchestrator – parses the classification and applies the routing rules and insufficiency gate in code:
//   out_of_scope                         → Fallback
//   about the project on file            → specialist agent
//   plan with a self-sufficient request  → Planner
//   anything else                        → Clarifier (never generate from too little information)

const requests = $('Orchestrator: Build Prompt').all();
const AGENT = { plan: 'planner', risk: 'risk', status: 'status', milestone: 'milestone', comms: 'comms' };

return $input.all().map((item, i) => {
  const { openaiRequest, ...req } = requests[i].json;
  const body = item.json.body ?? item.json;
  const headers = item.json.headers ?? {};
  const finishedAt = new Date().toISOString();

  let d;
  try { d = JSON.parse(body.choices?.[0]?.message?.content ?? ''); } catch (e) { d = null; }
  d = d ?? { intent: 'out_of_scope', uses_project_on_file: false, request_details_sufficient: false, sprint: null, window_days: null, reason: 'Orchestrator output could not be parsed.' };

  let route, gate;
  if (d.intent === 'out_of_scope') { route = 'fallback'; gate = 'out of scope'; }
  else if (d.uses_project_on_file) { route = AGENT[d.intent]; gate = 'project data on file'; }
  else if (d.intent === 'plan' && d.request_details_sufficient) { route = 'planner'; gate = 'request states objective, scope and timeline/team'; }
  else { route = 'clarifier'; gate = d.intent === 'plan' ? 'request lacks objective, scope or timeline/team' : `no project data for a ${d.intent} request`; }

  const latencyMs = Number(headers['openai-processing-ms']) || (Date.parse(finishedAt) - Date.parse(req.orchestrator_started_at));
  return {
    json: {
      ...req,
      route,
      intent: d.intent,
      uses_project_on_file: d.uses_project_on_file,
      sprint: d.sprint,
      window_days: d.window_days,
      decision: { ...d, route, gate },
      orchestrator_run: {
        name: 'Orchestrator',
        run_type: 'llm',
        start_time: req.orchestrator_started_at,
        end_time: new Date(Date.parse(req.orchestrator_started_at) + latencyMs).toISOString(),
        inputs: { messages: openaiRequest.messages },
        outputs: body,
        model: openaiRequest.model,
        temperature: openaiRequest.temperature,
      },
    },
  };
});

// Fallback – deterministic reply for out-of-scope requests (no LLM call).

const CAPABILITIES = [
  '**Project plan** – e.g. "Generate a project plan for the AI Adoption Project at ABCDE Ltd."',
  '**Risk assessment** – e.g. "What are the top 3 risks for the ABCDE Ltd project?"',
  '**Weekly status report** – e.g. "Generate a weekly status report for Sprint 3."',
  '**Milestone & deadline alerts** – e.g. "Which tasks are blocked or at risk of missing their deadline?"',
  '**Stakeholder update email** – e.g. "Draft a stakeholder update for Sprint 2."',
];

return $input.all().map(({ json: req }) => {
  const status = 'OUT_OF_SCOPE';
  const markdown = [
    "## That's outside what I can help with\n\nI'm Mira, a project intelligence assistant for the AI Adoption Project at ABCDE Ltd.",
    '**I can help with**', CAPABILITIES.map((c) => `- ${c}`).join('\n'),
  ].join('\n\n');
  const now = new Date().toISOString();
  return {
    json: {
      test_id: req.test_id,
      query: req.query,
      checks: req.checks,
      agent: 'Fallback',
      status,
      uses_project_data: false,
      grounding: null,
      markdown,
      usage: { input_tokens: 0, output_tokens: 0, total_tokens: 0 },
      trace: {
        name: 'Mira',
        start_time: now,
        end_time: now,
        inputs: { query: req.query },
        outputs: { status, response: markdown },
        tags: ['mira', 'fallback', req.test_id].filter(Boolean),
        metadata: { test_id: req.test_id, agent: 'Fallback', status },
        children: [],
      },
    },
  };
});

// Joins whichever agent branch ran for this request and nests the Orchestrator call into its trace,
// so LangSmith shows one trace per request: Orchestrator → specialist → checks.

const orch = $('Orchestrator: Route').all();

return $input.all().map((item, i) => {
  const out = item.json;
  const o = orch[i].json;
  const ou = o.orchestrator_run.outputs?.usage ?? {};
  const usage = {
    input_tokens: out.usage.input_tokens + (ou.prompt_tokens ?? 0),
    output_tokens: out.usage.output_tokens + (ou.completion_tokens ?? 0),
    total_tokens: out.usage.total_tokens + (ou.total_tokens ?? 0),
  };
  return {
    json: {
      ...out,
      route: o.route,
      intent: o.intent,
      decision: o.decision,
      usage,
      trace: {
        ...out.trace,
        start_time: o.orchestrator_started_at,
        tags: [...new Set([...out.trace.tags, `route:${o.route}`])],
        metadata: { ...out.trace.metadata, route: o.route, intent: o.intent, gate: o.decision.gate, total_tokens: usage.total_tokens },
        children: [o.orchestrator_run, ...out.trace.children],
      },
    },
  };
});

// Reusable: converts each item's `trace` descriptor into a LangSmith /runs/batch payload.
// Descriptor: { name, start_time, end_time, inputs, outputs, tags, metadata,
//               children: [{ name, run_type, start_time, end_time, inputs, outputs, model?, temperature? }] }

const cfg = $('Config').first().json;

// UUID v7 (time-ordered), which LangSmith expects for run IDs.
function uuidv7(ms) {
  const r = (n) => Array.from({ length: n }, () => Math.floor(Math.random() * 16).toString(16)).join('');
  const ts = ms.toString(16).padStart(12, '0');
  const variant = '89ab'[Math.floor(Math.random() * 4)];
  return `${ts.slice(0, 8)}-${ts.slice(8, 12)}-7${r(3)}-${variant}${r(3)}-${r(12)}`;
}

// LangSmith dotted_order segment: YYYYMMDDTHHMMSSffffffZ + run id
const dottedTs = (iso) => iso.replace(/[-:]/g, '').replace('.', '').replace('Z', '000Z');

function usageMetadata(outputs) {
  const u = outputs?.usage ?? {};
  return { input_tokens: u.prompt_tokens ?? 0, output_tokens: u.completion_tokens ?? 0, total_tokens: u.total_tokens ?? 0 };
}

return $input.all().map(({ json }) => {
  const t = json.trace;
  const rootStart = Date.parse(t.start_time);
  const traceId = uuidv7(rootStart);
  const rootDotted = dottedTs(t.start_time) + traceId;

  const root = {
    id: traceId,
    trace_id: traceId,
    dotted_order: rootDotted,
    name: t.name,
    run_type: 'chain',
    inputs: t.inputs,
    outputs: t.outputs,
    start_time: t.start_time,
    end_time: t.end_time,
    session_name: cfg.langsmithProject,
    tags: t.tags,
    extra: { metadata: { ...t.metadata, n8n_execution_id: $execution.id } },
  };

  // Children start strictly after the root (+1 ms each) so dotted_order stays monotonic.
  const children = (t.children ?? []).map((c, idx) => {
    const startMs = Math.max(Date.parse(c.start_time), rootStart + idx + 1);
    const start = new Date(startMs).toISOString();
    const end = new Date(Math.max(Date.parse(c.end_time), startMs)).toISOString();
    const id = uuidv7(startMs);
    const run = {
      id,
      trace_id: traceId,
      parent_run_id: traceId,
      dotted_order: `${rootDotted}.${dottedTs(start)}${id}`,
      name: c.name,
      run_type: c.run_type,
      inputs: c.inputs,
      outputs: c.outputs,
      start_time: start,
      end_time: end,
      session_name: cfg.langsmithProject,
    };
    if (c.run_type === 'llm') {
      run.outputs = { ...c.outputs, usage_metadata: usageMetadata(c.outputs) };
      run.extra = {
        metadata: { ls_provider: 'openai', ls_model_name: c.model, ls_model_type: 'chat', ls_temperature: c.temperature },
        invocation_params: { model: c.model, temperature: c.temperature },
      };
    }
    return run;
  });

  return { json: { test_id: json.test_id, trace_id: traceId, batch: { post: [root, ...children] } } };
});

// Loop-back: re-emit this request's response with its LangSmith trace ID (the API reply itself is not needed).
const traceIds = $('LangSmith: Build Trace').all().map((i) => i.json.trace_id);
return $('Collect Response').all().map((i, k) => {
  const { trace, ...rest } = i.json;
  return { json: { ...rest, langsmith_trace_id: traceIds[k] } };
});

// Clarifier – asks for the missing information instead of generating output from too little input.
// The checklist of required information depends on what the PM asked for (intent).

const cfg = $('Config').first().json;

const CHECKLIST = {
  plan: ['project scope', 'goals / objectives', 'key deliverables', 'timeline or deadline', 'team size and roles', 'constraints (budget, technology, stakeholders)'],
  risk: ['project scope and objectives', 'industry / domain', 'timeline and current phase', 'team size and roles', 'technology and systems involved', 'budget', 'key stakeholders and dependencies'],
  status: ['task list with statuses', 'task owners', 'due dates', 'sprint or reporting period', 'blockers', 'milestones'],
  milestone: ['project timeline with milestones and dates', 'task list with statuses', 'due dates', 'task owners', 'look-ahead window'],
  comms: ['audience', 'topic or reporting period', 'key updates and task progress', 'issues or asks', 'tone and format'],
};
const TASK = { plan: 'a project plan', risk: 'a risk assessment', status: 'a status report', milestone: 'milestone and deadline alerts', comms: 'a stakeholder update' };

const SYSTEM_PROMPT = `ROLE
You are the Clarifier inside Mira, a project intelligence assistant for PMs/TPMs at Nexora. The Orchestrator has decided that the request does not contain enough information to produce the requested output. Your job is to explain what is missing and ask the PM precise questions. You never produce the output itself – no plan, phases, risks, statuses, counts or percentages.

INPUT
- USER REQUEST, the requested output, and a REQUIRED INFORMATION checklist.

RULES
- reason: one sentence on why the output cannot be produced yet, naming the request.
- known_information: facts the request explicitly states (may be empty). Do not infer.
- missing_information: every checklist item that the request does not explicitly provide, using the checklist wording.
- questions: 4–7 specific questions, one per missing item where possible, that the PM can answer in a sentence.

OUTPUT
Return JSON matching the provided schema.`;

const strings = { type: 'array', items: { type: 'string' } };
const RESPONSE_FORMAT = {
  type: 'json_schema',
  json_schema: {
    name: 'clarifier_output',
    strict: true,
    schema: {
      type: 'object', additionalProperties: false,
      required: ['reason', 'known_information', 'missing_information', 'questions'],
      properties: { reason: { type: 'string' }, known_information: strings, missing_information: strings, questions: strings },
    },
  },
};

return $input.all().map(({ json: req }) => {
  const intent = CHECKLIST[req.intent] ? req.intent : 'plan';
  const userContent = `USER REQUEST:\n${req.query}\n\nREQUESTED OUTPUT: ${TASK[intent]}\n\n` +
    `REQUIRED INFORMATION:\n${CHECKLIST[intent].map((c) => `- ${c}`).join('\n')}`;
  return {
    json: {
      ...req,
      agent: 'Clarifier',
      clarify_for: intent,
      checklist: CHECKLIST[intent],
      started_at: new Date().toISOString(),
      openaiRequest: {
        model: cfg.model,
        temperature: Number(cfg.temperature),
        max_tokens: 800,
        response_format: RESPONSE_FORMAT,
        messages: [
          { role: 'system', content: SYSTEM_PROMPT },
          { role: 'user', content: userContent },
        ],
      },
    },
  };
});

// Clarifier – renders the clarification request, checks that every required checklist item was
// either acknowledged as known or asked for, and describes the trace.

const requests = $('Clarifier: Build Prompt').all();

const HEADING = {
  plan: '## More information needed before I can build a plan',
  risk: '## More information needed before I can assess risks',
  status: '## No task data available',
  milestone: '## No timeline or task data to track',
  comms: '## More information needed before I can draft the update',
};
const LEAD = {
  plan: '',
  risk: '',
  status: "I can't produce a status report from the request alone – there are no task statuses, owners or due dates to report on.",
  milestone: "I can't flag milestones or deadline risks without a timeline and task due dates.",
  comms: '',
};
const FOOTER = {
  plan: '_No plan was generated, to avoid inventing scope, milestones or dates that you have not provided._',
  risk: '_No risks were listed, to avoid inventing project-specific risks without project data._',
  status: '_No task statuses, counts or progress percentages were generated._',
  milestone: '_No milestones or dates were generated._',
  comms: '_No email was drafted, to avoid inventing progress or results._',
};
const list = (items) => (items.length ? items.map((x) => `- ${x}`).join('\n') : '- _None._');
const stems = (s) => String(s).toLowerCase().replace(/[^a-z ]+/g, ' ').split(' ').filter((w) => w.length > 3).map((w) => w.slice(0, 5));

// Each checklist item must be covered by the known or missing lists (stem match on its key words).
function coverageCheck(checklist, c) {
  const covered = new Set(stems([...c.known_information, ...c.missing_information].join(' ')));
  const uncovered = checklist.filter((item) => !stems(item).some((s) => covered.has(s)));
  return { checked: checklist.length, covered: checklist.length - uncovered.length, uncovered };
}

return $input.all().map((item, i) => {
  const req = requests[i].json;
  const body = item.json.body ?? item.json;
  const headers = item.json.headers ?? {};
  const finishedAt = new Date().toISOString();
  const intent = req.clarify_for;

  let c;
  try { c = JSON.parse(body.choices?.[0]?.message?.content ?? ''); } catch (e) { c = null; }
  c = c ?? { reason: 'The request does not contain enough information.', known_information: [], missing_information: req.checklist, questions: [] };
  const coverage = coverageCheck(req.checklist, c);

  const markdown = [
    HEADING[intent],
    LEAD[intent],
    c.reason,
    '**What I have so far**', list(c.known_information),
    '**What is missing**', list(c.missing_information),
    '**Please answer these questions**',
    c.questions.map((q, k) => `${k + 1}. ${q}`).join('\n'),
    FOOTER[intent],
    '---',
    `Checklist coverage: ${coverage.covered}/${coverage.checked} required items addressed` +
      (coverage.uncovered.length ? `\n${coverage.uncovered.map((u) => `- ⚠ not asked: ${u}`).join('\n')}` : ' ✅'),
  ].filter(Boolean).join('\n\n');

  const latencyMs = Number(headers['openai-processing-ms']) || (Date.parse(finishedAt) - Date.parse(req.started_at));
  const llmEnd = new Date(Date.parse(req.started_at) + latencyMs).toISOString();
  const usage = body.usage ?? {};

  return {
    json: {
      test_id: req.test_id,
      query: req.query,
      checks: req.checks,
      agent: req.agent,
      status: 'NEEDS_CLARIFICATION',
      uses_project_data: false,
      coverage,
      grounding: null,
      markdown,
      usage: { input_tokens: usage.prompt_tokens ?? 0, output_tokens: usage.completion_tokens ?? 0, total_tokens: usage.total_tokens ?? 0 },
      trace: {
        name: 'Mira',
        start_time: req.started_at,
        end_time: finishedAt,
        inputs: { query: req.query },
        outputs: { status: 'NEEDS_CLARIFICATION', response: markdown },
        tags: ['mira', 'clarifier', req.test_id].filter(Boolean),
        metadata: { test_id: req.test_id, agent: req.agent, clarify_for: intent, checklist_coverage: coverage.covered / coverage.checked },
        children: [
          {
            name: req.agent,
            run_type: 'llm',
            start_time: req.started_at,
            end_time: llmEnd,
            inputs: { messages: req.openaiRequest.messages },
            outputs: body,
            model: req.openaiRequest.model,
            temperature: req.openaiRequest.temperature,
          },
          {
            name: 'Checklist Coverage',
            run_type: 'chain',
            start_time: llmEnd,
            end_time: finishedAt,
            inputs: { checklist: req.checklist },
            outputs: coverage,
          },
        ],
      },
    },
  };
});

// Planner Agent – builds the OpenAI request for each incoming request item.
// Project data is attached only when the request refers to the ABCDE Ltd project, so the
// agent cannot borrow ABCDE facts to "fill in" a vague request about some other project.

const cfg = $('Config').first().json;
const kb = $('Knowledge Base').first().json;

const SYSTEM_PROMPT = `ROLE
You are the Planner Agent inside Mira, a project intelligence assistant for PMs/TPMs at Nexora. You turn project information into a structured project plan, and you refuse to plan when the information is insufficient.

INPUT
- USER REQUEST: what the PM asked for.
- PROJECT DATA (optional): <project_description> and <project_timeline> for a project on file. If PROJECT DATA is absent, the only information you have is the USER REQUEST text.

DECISION – choose exactly one status
1. PROJECT DATA is present → status "PLAN", built only from PROJECT DATA.
2. PROJECT DATA is absent → judge the USER REQUEST alone. It is sufficient ONLY if it explicitly states ALL of:
   (a) the objective / goals, (b) the scope or main deliverables, and (c) a timeline or team size.
   If any of these is missing → status "NEEDS_CLARIFICATION". A one-line idea ("build a chatbot") or a duration with no content ("a 2-week project") is NOT sufficient.

RULES FOR A PLAN (hallucination guardrails)
- objectives, scope, success_metrics, governance: include only items explicitly stated in the source. Each item's source_quote must be an exact, verbatim phrase copied from the source text. Never add goals, KPIs, technologies, budgets, vendors, or people that are not in the source.
- phases: copy every phase from <project_timeline> exactly – same number, name, weeks, dates, key activities and milestones/deliverables. Do not add, merge, split, rename or re-date phases.
- executive_summary: 2–3 sentences using only facts from the source.
- assumptions: things you had to assume to present the plan (keep minimal).
- open_questions: information a PM still needs that the source does NOT provide (e.g. budget, team size/named owners, tooling, which departments pilot first). Do not answer them yourself.
- If the source is internally inconsistent, say so in open_questions.

RULES FOR NEEDS_CLARIFICATION
- Set plan to null. Do NOT produce phases, milestones, or a draft plan.
- reason: one sentence on why a plan cannot be produced yet.
- known_information: what the request does state (may be empty).
- missing_information: always cover project scope, goals/objectives, key deliverables, timeline, team size/roles, and constraints (budget, technology, stakeholders) – unless explicitly given.
- questions: 4–7 specific questions the PM can answer to unblock planning.

OUTPUT
Return JSON matching the provided schema. Unused branch must be null.`;

const sourced = {
  type: 'object', additionalProperties: false, required: ['text', 'source_quote'],
  properties: { text: { type: 'string' }, source_quote: { type: 'string' } },
};
const strings = { type: 'array', items: { type: 'string' } };

const RESPONSE_FORMAT = {
  type: 'json_schema',
  json_schema: {
    name: 'planner_output',
    strict: true,
    schema: {
      type: 'object', additionalProperties: false, required: ['status', 'clarification', 'plan'],
      properties: {
        status: { type: 'string', enum: ['PLAN', 'NEEDS_CLARIFICATION'] },
        clarification: {
          anyOf: [{ type: 'null' }, {
            type: 'object', additionalProperties: false,
            required: ['reason', 'known_information', 'missing_information', 'questions'],
            properties: { reason: { type: 'string' }, known_information: strings, missing_information: strings, questions: strings },
          }],
        },
        plan: {
          anyOf: [{ type: 'null' }, {
            type: 'object', additionalProperties: false,
            required: ['project_name', 'executive_summary', 'objectives', 'scope', 'success_metrics', 'governance', 'phases', 'assumptions', 'open_questions'],
            properties: {
              project_name: { type: 'string' },
              executive_summary: { type: 'string' },
              objectives: { type: 'array', items: sourced },
              scope: { type: 'array', items: sourced },
              success_metrics: { type: 'array', items: sourced },
              governance: { type: 'array', items: sourced },
              phases: {
                type: 'array',
                items: {
                  type: 'object', additionalProperties: false,
                  required: ['phase_number', 'name', 'start_week', 'end_week', 'start_date', 'end_date', 'key_activities', 'milestones_deliverables'],
                  properties: {
                    phase_number: { type: 'integer' }, name: { type: 'string' },
                    start_week: { type: 'integer' }, end_week: { type: 'integer' },
                    start_date: { type: 'string' }, end_date: { type: 'string' },
                    key_activities: strings, milestones_deliverables: strings,
                  },
                },
              },
              assumptions: strings,
              open_questions: strings,
            },
          }],
        },
      },
    },
  },
};

// The Orchestrator decides this (uses_project_on_file); the regex is the fallback for the standalone step workflows.
const refersToProject = (q) => /ABCDE|AI Adoption Project/i.test(q);

function projectDataBlock() {
  const phases = kb.timeline.map((p) => [
    `Phase ${p.phase}: ${p.phase_name} | Weeks ${p.start_week}-${p.end_week} | ${p.start_date} to ${p.end_date}`,
    `  Key activities: ${p.key_activities.join('; ')}`,
    `  Milestones/deliverables: ${p.milestones.join('; ')}`,
  ].join('\n')).join('\n');
  return `PROJECT DATA – ${kb.project.name}\n<project_description>\n${kb.project.description}\n</project_description>\n` +
    `<project_timeline>\nWeek 1 starts ${kb.facts.project_start_date}.\n${phases}\n</project_timeline>`;
}

return $input.all().map(({ json: req }) => {
  const usesProjectData = req.uses_project_on_file ?? refersToProject(req.query);
  const userContent = `USER REQUEST:\n${req.query}\n\n` +
    (usesProjectData ? projectDataBlock() : 'PROJECT DATA: none provided.');
  const messages = [
    { role: 'system', content: SYSTEM_PROMPT },
    { role: 'user', content: userContent },
  ];
  return {
    json: {
      ...req,
      agent: 'Planner Agent',
      uses_project_data: usesProjectData,
      source_text: usesProjectData ? kb.project.description : req.query,
      started_at: new Date().toISOString(),
      openaiRequest: {
        model: cfg.model,
        temperature: Number(cfg.temperature),
        max_tokens: Number(cfg.maxTokens),
        response_format: RESPONSE_FORMAT,
        messages,
      },
    },
  };
});

// Planner Agent – parses the model output, verifies grounding against the source data,
// renders Markdown for the PM, and describes the LangSmith trace for this request.

const kb = $('Knowledge Base').first().json;
const requests = $('Planner: Build Prompt').all();

const norm = (s) => String(s ?? '').toLowerCase().replace(/[^a-z0-9%]+/g, ' ').trim();
const list = (items) => (items.length ? items.map((x) => `- ${x}`).join('\n') : '- _None stated in the source._');
const sourcedList = (items) => (items.length
  ? items.map((x) => `- ${x.text}  \n  _Source: “${x.source_quote}”_`).join('\n')
  : '- _None stated in the source._');

// Every plan item must trace back to the source; phases must match the timeline exactly.
function groundingCheck(plan, req) {
  const issues = [];
  let checked = 0, grounded = 0;
  const source = norm(req.source_text);

  for (const key of ['objectives', 'scope', 'success_metrics', 'governance']) {
    for (const item of plan[key]) {
      checked++;
      if (item.source_quote && source.includes(norm(item.source_quote))) grounded++;
      else issues.push(`${key}: quote not found in source → “${item.source_quote}”`);
    }
  }

  if (req.uses_project_data) {
    const timeline = new Map(kb.timeline.map((p) => [p.phase, p]));
    const known = new Set(kb.milestones.map((m) => norm(m.milestone)));
    if (plan.phases.length !== kb.timeline.length) {
      issues.push(`phase count ${plan.phases.length} ≠ timeline ${kb.timeline.length}`);
    }
    for (const p of plan.phases) {
      checked++;
      const t = timeline.get(p.phase_number);
      const problems = [];
      if (!t) problems.push('phase not in timeline');
      else {
        if (norm(p.name) !== norm(t.phase_name)) problems.push(`name “${p.name}”`);
        if (p.start_date !== t.start_date || p.end_date !== t.end_date) problems.push(`dates ${p.start_date}→${p.end_date}`);
        const invented = p.milestones_deliverables.filter((m) => !known.has(norm(m)));
        if (invented.length) problems.push(`milestones not in timeline: ${invented.join('; ')}`);
      }
      if (problems.length) issues.push(`Phase ${p.phase_number}: ${problems.join(', ')}`);
      else grounded++;
    }
  }

  return { checked, grounded, score: checked ? grounded / checked : 1, issues };
}

function renderPlan(plan, req, grounding) {
  const statusOf = new Map(kb.timeline.map((p) => [p.phase, p.schedule_status]));
  const rows = plan.phases.map((p) =>
    `| ${p.phase_number}. ${p.name} | W${p.start_week}–W${p.end_week} | ${p.start_date} → ${p.end_date} | ` +
    `${p.key_activities.join('; ')} | ${p.milestones_deliverables.join('; ')} | ${req.uses_project_data ? statusOf.get(p.phase_number) ?? '—' : '—'} |`);
  const sources = req.uses_project_data ? 'project_description.txt, project_timeline.csv' : 'user request';
  return [
    `# Project Plan — ${plan.project_name}`,
    `_Generated by Mira · as of ${kb.facts.as_of_date} · Sources: ${sources}_`,
    '## Executive summary', plan.executive_summary,
    '## Objectives', sourcedList(plan.objectives),
    '## Scope', sourcedList(plan.scope),
    '## Timeline, milestones & deliverables',
    ['| Phase | Weeks | Dates | Key activities | Milestones / deliverables | Schedule status |',
      '|---|---|---|---|---|---|', ...rows].join('\n'),
    '## Success metrics', sourcedList(plan.success_metrics),
    '## Team & governance', sourcedList(plan.governance),
    '## Assumptions', list(plan.assumptions),
    '## Open questions for the PM', list(plan.open_questions),
    '---',
    `Grounding check: ${grounding.grounded}/${grounding.checked} items traced to source` +
      (grounding.issues.length ? `\n${grounding.issues.map((i) => `- ⚠ ${i}`).join('\n')}` : ' ✅'),
  ].join('\n\n');
}

function renderClarification(c) {
  return [
    '## More information needed before I can build a plan',
    c.reason,
    '**What I have so far**', list(c.known_information),
    '**What is missing**', list(c.missing_information),
    '**Please answer these questions**',
    c.questions.map((q, i) => `${i + 1}. ${q}`).join('\n'),
    '_No plan was generated, to avoid inventing scope, milestones or dates that you have not provided._',
  ].join('\n\n');
}

return $input.all().map((item, i) => {
  const req = requests[i].json;
  const body = item.json.body ?? item.json;
  const headers = item.json.headers ?? {};
  const finishedAt = new Date().toISOString();
  const content = body.choices?.[0]?.message?.content ?? '';

  let output = null, parseError = null;
  try { output = JSON.parse(content); } catch (e) { parseError = e.message; }

  let markdown, grounding = null;
  if (!output) {
    markdown = `⚠ Planner Agent returned unparseable output (${parseError}).\n\n${content}`;
  } else if (output.status === 'PLAN' && output.plan) {
    grounding = groundingCheck(output.plan, req);
    markdown = renderPlan(output.plan, req, grounding);
  } else {
    markdown = renderClarification(output.clarification ?? { reason: 'Insufficient detail.', known_information: [], missing_information: [], questions: [] });
  }

  // Model latency from OpenAI's header gives accurate per-call timing even when items run in sequence.
  const latencyMs = Number(headers['openai-processing-ms']) || (Date.parse(finishedAt) - Date.parse(req.started_at));
  const llmEnd = new Date(Date.parse(req.started_at) + latencyMs).toISOString();
  const usage = body.usage ?? {};
  const status = output?.status ?? 'ERROR';

  return {
    json: {
      test_id: req.test_id,
      query: req.query,
      checks: req.checks,
      agent: req.agent,
      status,
      uses_project_data: req.uses_project_data,
      phase_count: output?.plan?.phases?.length ?? 0,
      grounding,
      markdown,
      usage: { input_tokens: usage.prompt_tokens ?? 0, output_tokens: usage.completion_tokens ?? 0, total_tokens: usage.total_tokens ?? 0 },
      trace: {
        name: 'Mira',
        start_time: req.started_at,
        end_time: finishedAt,
        inputs: { query: req.query },
        outputs: { status, response: markdown },
        tags: ['mira', 'planner', req.test_id].filter(Boolean),
        metadata: { test_id: req.test_id, agent: req.agent, status, uses_project_data: req.uses_project_data, groundedness: grounding?.score ?? null, as_of_date: kb.facts.as_of_date },
        children: [
          {
            name: req.agent,
            run_type: 'llm',
            start_time: req.started_at,
            end_time: llmEnd,
            inputs: { messages: req.openaiRequest.messages },
            outputs: body,
            model: req.openaiRequest.model,
            temperature: req.openaiRequest.temperature,
          },
          {
            name: 'Grounding Check',
            run_type: 'chain',
            start_time: llmEnd,
            end_time: finishedAt,
            inputs: { status, uses_project_data: req.uses_project_data },
            outputs: grounding ?? { skipped: 'no plan generated' },
          },
        ],
      },
    },
  };
});

// Risk Assessor – builds the OpenAI request for each incoming request item.
// The model only rates and links register risks by ID (one schema key per risk); risk text and
// mitigations are copied from project_risks.csv by code, so no risk can be invented.

const cfg = $('Config').first().json;
const kb = $('Knowledge Base').first().json;

const SYSTEM_PROMPT = `ROLE
You are the Risk Assessor inside Mira, a project intelligence assistant for PMs/TPMs at Nexora. You assess a project's risks using only its risk register and project data, and you refuse to assess when there is no project data.

INPUT
- USER REQUEST: what the PM asked for.
- PROJECT DATA (optional): <project_description>, <schedule> (phases with schedule status), <task_board> (tasks with status and due dates, plus blocked/overdue lists) and <risk_register> (risks R01..Rnn). If PROJECT DATA is absent, the only information you have is the USER REQUEST text.

DECISION – choose exactly one status
1. PROJECT DATA is absent → status "NEEDS_CLARIFICATION". A risk assessment needs a known project; never produce risks from a one-line request.
2. PROJECT DATA is present and the PM asks for the top / most important / biggest N risks → status "TOP_RISKS", requested_count = N (default 3).
3. PROJECT DATA is present otherwise → status "ASSESSMENT", requested_count = number of risks in the register.

RULES FOR AN ASSESSMENT (both TOP_RISKS and ASSESSMENT) – hallucination guardrails
- summary: 2–3 sentences on the overall risk picture for this project at its current phase. Do not number or rank risks in the summary; ranking is computed separately.
- risks has one entry per register risk ID. Fill in EVERY entry, also when the PM asks only for the top N – the top N are selected by code from your ratings. Do not create risks that are not in the register.
- likelihood and impact (High / Medium / Low) must reflect THIS project: its logistics domain, its use cases (demand forecasting, route optimization, inventory management, customer support), the current phase, and live task-board signals. Do not rate everything High.
- If any related task is Blocked or Overdue, likelihood must be Medium or High – the problem is already showing.
- priority_rank: your overall order 1..n (1 = most urgent), unique per risk. Use it to break ties between equal ratings.
- rationale: 1–2 sentences on why this risk matters for this project now. Cite a specific project fact – a use case, goal, phase, or task ID. Never use generic statements such as "this is common in AI projects".
- evidence_quote: choose from the allowed list the project goal, use case or capability this risk threatens most (e.g. "route optimization", "reducing delivery delays by 15%"). Prefer the most specific phrase.
- affected_use_cases: the 1–2 logistics use cases this risk would hit HARDEST, so the PM can see where each risk bites (e.g. data-quality risk → demand forecasting, inventory management; legacy-integration risk → route optimization). Do not list every use case for every risk. Use an empty array only if the risk is truly organisation-wide.
- related_task_ids: task IDs from <task_board> that are signals for this risk (e.g. a blocked security review → security risk). Empty array if none. Never use IDs that are not on the board.
- exposed_phase: the phase number from <schedule> where this risk is most likely to materialise.
- owner_role: who on the cross-functional task force should own it.
- next_step: one full sentence (8–30 words) stating a concrete action that applies the register's mitigation to THIS project – what to do, and on which use case, data, system or task. Do not copy the mitigation text and do not just name a phase. Example for a data risk: "Run a data-quality audit of historical delivery and inventory records and close the gaps found in T006."
- next_step_before_phase: the phase number by whose start the next step must be done. It must be the current phase or a later one.

RULES FOR NEEDS_CLARIFICATION
- Set assessment to null. Do NOT list risks, generic or otherwise.
- reason: one sentence on why risks cannot be assessed yet.
- known_information: what the request does state (may be empty).
- missing_information: always cover project scope and objectives, industry/domain, timeline and current phase, team size/roles, technology and systems involved, budget, and key stakeholders/dependencies – unless explicitly given.
- questions: 4–7 specific questions the PM can answer to unblock the assessment.

OUTPUT
Return JSON matching the provided schema. Unused branch must be null.`;

const riskIds = kb.risks.map((r) => r.risk_id);
const taskIds = kb.tasks.map((t) => t.task_id);
const phaseNumbers = kb.timeline.map((p) => p.phase);
const level = { type: 'string', enum: ['High', 'Medium', 'Low'] };
const strings = { type: 'array', items: { type: 'string' } };

// One required key per register risk: strict mode then forces the model to rate all of them.
const riskRating = {
  type: 'object', additionalProperties: false,
  required: ['likelihood', 'impact', 'priority_rank', 'rationale', 'evidence_quote', 'affected_use_cases',
    'related_task_ids', 'exposed_phase', 'owner_role', 'next_step', 'next_step_before_phase'],
  properties: {
    likelihood: level,
    impact: level,
    priority_rank: { type: 'integer' },
    rationale: { type: 'string' },
    // Verbatim description phrases extracted by the Knowledge Base – a citation can't be invented.
    evidence_quote: { type: 'string', enum: kb.project.outcome_phrases },
    affected_use_cases: { type: 'array', items: { type: 'string', enum: kb.project.use_cases } },
    related_task_ids: { type: 'array', items: { type: 'string', enum: taskIds } },
    exposed_phase: { type: 'integer', enum: phaseNumbers },
    owner_role: { type: 'string', enum: ['Data scientists', 'IT professionals', 'Business stakeholders', 'Cross-functional task force'] },
    next_step: { type: 'string' },
    next_step_before_phase: { type: 'integer', enum: phaseNumbers },
  },
};

const RESPONSE_FORMAT = {
  type: 'json_schema',
  json_schema: {
    name: 'risk_output',
    strict: true,
    schema: {
      type: 'object', additionalProperties: false, required: ['status', 'clarification', 'assessment'],
      properties: {
        status: { type: 'string', enum: ['ASSESSMENT', 'TOP_RISKS', 'NEEDS_CLARIFICATION'] },
        clarification: {
          anyOf: [{ type: 'null' }, {
            type: 'object', additionalProperties: false,
            required: ['reason', 'known_information', 'missing_information', 'questions'],
            properties: { reason: { type: 'string' }, known_information: strings, missing_information: strings, questions: strings },
          }],
        },
        assessment: {
          anyOf: [{ type: 'null' }, {
            type: 'object', additionalProperties: false,
            required: ['requested_count', 'summary', 'risks'],
            properties: {
              requested_count: { type: 'integer' },
              summary: { type: 'string' },
              risks: {
                type: 'object', additionalProperties: false, required: riskIds,
                properties: Object.fromEntries(riskIds.map((id) => [id, riskRating])),
              },
            },
          }],
        },
      },
    },
  },
};

// The Orchestrator decides this (uses_project_on_file); the regex is the fallback for the standalone step workflows.
const refersToProject = (q) => /ABCDE|AI Adoption Project/i.test(q);

function projectDataBlock() {
  const f = kb.facts;
  const schedule = kb.timeline.map((p) =>
    `Phase ${p.phase}: ${p.phase_name} | ${p.start_date} to ${p.end_date} | ${p.schedule_status}`).join('\n');
  const tasks = kb.tasks.map((t) =>
    `${t.task_id} | ${t.task_name} | ${t.status} | ${t.priority} | ${t.sprint} | due ${t.due_date}`).join('\n');
  const listIds = (ts) => (ts.length ? ts.map((t) => `${t.task_id} ${t.task_name}`).join('; ') : 'none');
  const register = kb.risks.map((r) =>
    `${r.risk_id} | ${r.category} | ${r.risk_challenge} | Impact: ${r.impact} | Mitigation: ${r.mitigation_strategy}`).join('\n');
  return `PROJECT DATA – ${kb.project.name}\n` +
    `<project_description>\n${kb.project.description}\n</project_description>\n` +
    `<schedule>\nAs of ${f.as_of_date} (week ${f.current_week} of ${f.total_weeks}); current phase: ${f.current_phase}.\n${schedule}\n</schedule>\n` +
    `<task_board>\nTask | Name | Status | Priority | Sprint | Due\n${tasks}\n` +
    `Blocked: ${listIds(f.blocked_tasks)}\nOverdue: ${listIds(f.overdue_tasks)}\n</task_board>\n` +
    `<risk_register>\n${register}\n</risk_register>`;
}

return $input.all().map(({ json: req }) => {
  const usesProjectData = req.uses_project_on_file ?? refersToProject(req.query);
  const userContent = `USER REQUEST:\n${req.query}\n\n` +
    (usesProjectData ? projectDataBlock() : 'PROJECT DATA: none provided.');
  const messages = [
    { role: 'system', content: SYSTEM_PROMPT },
    { role: 'user', content: userContent },
  ];
  return {
    json: {
      ...req,
      agent: 'Risk Assessor',
      uses_project_data: usesProjectData,
      source_text: usesProjectData ? kb.project.description : req.query,
      started_at: new Date().toISOString(),
      openaiRequest: {
        model: cfg.model,
        temperature: Number(cfg.temperature),
        max_tokens: Number(cfg.maxTokens),
        response_format: RESPONSE_FORMAT,
        messages,
      },
    },
  };
});

// Risk Assessor – parses the model output, verifies it against the risk register and task board,
// ranks risks in code (likelihood × impact, model rank as tie-break), renders Markdown,
// and describes the LangSmith trace for this request.

const kb = $('Knowledge Base').first().json;
const requests = $('Risk Assessor: Build Prompt').all();

const SCORE = { High: 3, Medium: 2, Low: 1 };
const register = new Map(kb.risks.map((r) => [r.risk_id, r]));
const tasksById = new Map(kb.tasks.map((t) => [t.task_id, t]));
const phases = new Map(kb.timeline.map((p) => [p.phase, p]));

const norm = (s) => String(s ?? '').toLowerCase().replace(/[^a-z0-9%]+/g, ' ').trim();

// Quote must appear as a contiguous word sequence in the source, tolerating inflection only
// ("reduce" ≈ "reducing"): each word is compared on its first 5 letters.
const stems = (s) => norm(s).split(' ').filter(Boolean).map((w) => w.slice(0, 5));
function quoteInSource(quote, source) {
  const q = stems(quote), src = stems(source);
  if (!q.length) return false;
  for (let i = 0; i + q.length <= src.length; i++) {
    if (q.every((w, j) => src[i + j] === w)) return true;
  }
  return false;
}
const cell = (s) => String(s ?? '').replace(/\|/g, '/').replace(/\n/g, ' ');
const list = (items) => (items.length ? items.map((x) => `- ${x}`).join('\n') : '- _None._');

// Every assessed risk must exist in the register exactly once, cite the description verbatim,
// and link only to real tasks and phases.
function groundingCheck(a, req) {
  const issues = [];
  let checked = 0, grounded = 0;
  const seen = new Set();

  for (const r of a.risks) {
    checked++;
    const problems = [];
    if (!register.has(r.risk_id)) problems.push('not in register');
    if (seen.has(r.risk_id)) problems.push('duplicate');
    seen.add(r.risk_id);
    if (!quoteInSource(r.evidence_quote, req.source_text)) problems.push(`quote not in description → “${r.evidence_quote}”`);
    const unknownTasks = r.related_task_ids.filter((id) => !tasksById.has(id));
    if (unknownTasks.length) problems.push(`unknown tasks ${unknownTasks.join(', ')}`);
    if (!phases.has(r.exposed_phase)) problems.push(`unknown phase ${r.exposed_phase}`);
    if (problems.length) issues.push(`${r.risk_id}: ${problems.join(', ')}`);
    else grounded++;
  }
  const missing = kb.risks.map((r) => r.risk_id).filter((id) => !seen.has(id));
  if (missing.length) issues.push(`register risks not assessed: ${missing.join(', ')}`);

  return { checked, grounded, score: checked ? grounded / checked : 1, issues };
}

// Review checks: ratings must agree with the task board (a blocked or overdue linked task means the
// risk is already showing); next steps must be a real action, not the register text or a bare phase
// reference; and their deadline must not already be in the past.
const overdueIds = new Set(kb.facts.overdue_tasks.map((t) => t.task_id));
const currentPhase = kb.timeline.find((p) => p.schedule_status === 'Current')?.phase ?? 1;
const phaseWords = new Set(kb.timeline.flatMap((p) => norm(p.phase_name).split(' ')).concat(['before', 'by', 'phase', 'start', 'of', 'the']));
function reviewCheck(risks) {
  const allCases = kb.project.use_cases.length;
  const undifferentiated = risks.filter((r) => r.affected_use_cases.length >= allCases).length;
  const domain = !risks.some((r) => r.affected_use_cases.length) ? ['no risk is tied to a logistics use case']
    : undifferentiated > risks.length / 2 ? [`${undifferentiated}/${risks.length} risks list every use case – not differentiated`] : [];
  return domain.concat(risks.flatMap((r) => {
    const issues = [];
    const live = r.related_task_ids.filter((id) => tasksById.get(id)?.status === 'Blocked' || overdueIds.has(id));
    if (r.likelihood === 'Low' && live.length) issues.push(`${r.risk_id}: likelihood Low but linked task ${live.join(', ')} is blocked/overdue`);
    const words = norm(r.next_step).split(' ').filter(Boolean);
    const content = words.filter((w) => !phaseWords.has(w) && !/^\d+$/.test(w));
    const mitigation = new Set(norm(register.get(r.risk_id)?.mitigation_strategy).split(' '));
    const copied = words.length && words.filter((w) => mitigation.has(w)).length / words.length > 0.8;
    if (content.length < 5) issues.push(`${r.risk_id}: next step is not an action (“${r.next_step}”)`);
    else if (copied) issues.push(`${r.risk_id}: next step copies the register mitigation`);
    if (r.next_step_before_phase < currentPhase) issues.push(`${r.risk_id}: next step deadline Phase ${r.next_step_before_phase} has already passed`);
    return issues;
  }));
}

const useCases = (r) => (r.affected_use_cases.length ? r.affected_use_cases.join(', ') : 'Organisation-wide');
const nextStep = (r) => `${r.next_step} _(before ${phaseLabel(r.next_step_before_phase)})_`;

// Deterministic ranking: score desc, then impact, then the model's priority_rank.
function rank(risks) {
  return [...risks]
    .map((r) => ({ ...r, score: SCORE[r.likelihood] * SCORE[r.impact] }))
    .sort((x, y) => y.score - x.score || SCORE[y.impact] - SCORE[x.impact] || x.priority_rank - y.priority_rank)
    .map((r, i) => ({ ...r, rank: i + 1 }));
}

const signals = (r) => (r.related_task_ids.length
  ? r.related_task_ids.map((id) => `${id} ${tasksById.get(id)?.task_name ?? '?'} (${tasksById.get(id)?.status ?? '?'})`).join('; ')
  : '—');
const phaseLabel = (n) => (phases.has(n) ? `Phase ${n}: ${phases.get(n).phase_name}` : `Phase ${n}`);

function renderAssessment(status, a, ranked, grounding, review) {
  const top = status === 'TOP_RISKS';
  const shown = top ? ranked.slice(0, Math.max(1, a.requested_count)) : ranked;
  const f = kb.facts;
  const header = [
    `# ${top ? `Top ${shown.length} Risks` : 'Risk Assessment'} — ${kb.project.name}`,
    `_Generated by Mira · as of ${f.as_of_date} (week ${f.current_week}, ${f.current_phase}) · Sources: project_risks.csv, project_description.txt, sample_task_board.csv, project_timeline.csv_`,
    '## Summary', a.summary,
  ];

  const body = top
    ? shown.map((r) => {
      const reg = register.get(r.risk_id);
      return [
        `### ${r.rank}. ${r.risk_id} — ${reg.category}: ${reg.risk_challenge}`,
        `**Likelihood:** ${r.likelihood} · **Impact:** ${r.impact} · **Score:** ${r.score}/9 · **Most exposed:** ${phaseLabel(r.exposed_phase)} · **Owner:** ${r.owner_role}`,
        `**Why it matters now:** ${r.rationale}`,
        `_Threatens: “${r.evidence_quote}” · Use cases affected: ${useCases(r)}_`,
        `**Impact if it happens (register):** ${reg.impact}`,
        `**Live signals on the task board:** ${signals(r)}`,
        `**Mitigation (register):** ${reg.mitigation_strategy}`,
        `**Recommended next step:** ${nextStep(r)}`,
      ].join('\n\n');
    })
    : [
      '## Risk register (ranked by likelihood × impact)',
      ['| # | ID | Category | Risk | L | I | Score | Use cases affected | Most exposed | Live signals | Owner |',
        '|---|---|---|---|---|---|---|---|---|---|---|',
        ...shown.map((r) => {
          const reg = register.get(r.risk_id);
          return `| ${r.rank} | ${r.risk_id} | ${cell(reg.category)} | ${cell(reg.risk_challenge)} | ${r.likelihood} | ${r.impact} | ${r.score} | ${cell(useCases(r))} | ${cell(phaseLabel(r.exposed_phase))} | ${cell(signals(r))} | ${r.owner_role} |`;
        })].join('\n'),
      '## Why each risk matters & what to do',
      shown.map((r) => {
        const reg = register.get(r.risk_id);
        return `**${r.rank}. ${r.risk_id} ${reg.category}** — ${r.rationale}  \n` +
          `_Threatens: “${r.evidence_quote}”_  \n` +
          `Impact (register): ${reg.impact}  \n` +
          `Mitigation (register): ${reg.mitigation_strategy}  \n` +
          `Next step: ${nextStep(r)}`;
      }).join('\n\n'),
    ];

  return [
    ...header,
    ...body,
    '---',
    `Grounding check: ${grounding.grounded}/${grounding.checked} risks traced to the register and source` +
      (grounding.issues.length ? `\n${grounding.issues.map((i) => `- ⚠ ${i}`).join('\n')}` : ' ✅'),
    `Review checks (task-board consistency, actionable next steps):` +
      (review.length ? `\n${review.map((i) => `- ⚠ ${i}`).join('\n')}` : ' ✅'),
  ].join('\n\n');
}

function renderClarification(c) {
  return [
    '## More information needed before I can assess risks',
    c.reason,
    '**What I have so far**', list(c.known_information),
    '**What is missing**', list(c.missing_information),
    '**Please answer these questions**',
    c.questions.map((q, i) => `${i + 1}. ${q}`).join('\n'),
    '_No risks were listed, to avoid inventing project-specific risks without project data._',
  ].join('\n\n');
}

return $input.all().map((item, i) => {
  const req = requests[i].json;
  const body = item.json.body ?? item.json;
  const headers = item.json.headers ?? {};
  const finishedAt = new Date().toISOString();
  const content = body.choices?.[0]?.message?.content ?? '';

  let output = null, parseError = null;
  try { output = JSON.parse(content); } catch (e) { parseError = e.message; }

  let markdown, grounding = null, review = [], ranked = [], shownCount = 0;
  const status = output?.status ?? 'ERROR';
  if (!output) {
    markdown = `⚠ Risk Assessor returned unparseable output (${parseError}).\n\n${content}`;
  } else if (status !== 'NEEDS_CLARIFICATION' && output.assessment) {
    // Schema returns { R01: {...}, R02: {...} }; flatten to a list keyed by risk_id.
    const a = { ...output.assessment, risks: Object.entries(output.assessment.risks).map(([risk_id, r]) => ({ risk_id, ...r })) };
    grounding = groundingCheck(a, req);
    review = reviewCheck(a.risks);
    ranked = rank(a.risks);
    shownCount = status === 'TOP_RISKS' ? Math.min(ranked.length, Math.max(1, a.requested_count)) : ranked.length;
    markdown = renderAssessment(status, a, ranked, grounding, review);
  } else {
    markdown = renderClarification(output.clarification ?? { reason: 'Insufficient detail.', known_information: [], missing_information: [], questions: [] });
  }

  // Model latency from OpenAI's header gives accurate per-call timing even when items run in sequence.
  const latencyMs = Number(headers['openai-processing-ms']) || (Date.parse(finishedAt) - Date.parse(req.started_at));
  const llmEnd = new Date(Date.parse(req.started_at) + latencyMs).toISOString();
  const usage = body.usage ?? {};
  const topRisks = ranked.slice(0, shownCount).map((r) => `${r.risk_id} (${r.likelihood}/${r.impact})`);

  return {
    json: {
      test_id: req.test_id,
      query: req.query,
      checks: req.checks,
      agent: req.agent,
      status,
      uses_project_data: req.uses_project_data,
      risk_count: shownCount,
      assessed_count: ranked.length,
      top_risks: topRisks,
      grounding,
      review,
      review_issue_count: review.length,
      markdown,
      usage: { input_tokens: usage.prompt_tokens ?? 0, output_tokens: usage.completion_tokens ?? 0, total_tokens: usage.total_tokens ?? 0 },
      trace: {
        name: 'Mira',
        start_time: req.started_at,
        end_time: finishedAt,
        inputs: { query: req.query },
        outputs: { status, response: markdown },
        tags: ['mira', 'risk', req.test_id].filter(Boolean),
        metadata: { test_id: req.test_id, agent: req.agent, status, uses_project_data: req.uses_project_data, groundedness: grounding?.score ?? null, as_of_date: kb.facts.as_of_date },
        children: [
          {
            name: req.agent,
            run_type: 'llm',
            start_time: req.started_at,
            end_time: llmEnd,
            inputs: { messages: req.openaiRequest.messages },
            outputs: body,
            model: req.openaiRequest.model,
            temperature: req.openaiRequest.temperature,
          },
          {
            name: 'Grounding Check',
            run_type: 'chain',
            start_time: llmEnd,
            end_time: finishedAt,
            inputs: { status, uses_project_data: req.uses_project_data },
            outputs: grounding ? { ...grounding, review, ranking: ranked.map((r) => `${r.rank}. ${r.risk_id} score ${r.score}`) } : { skipped: 'no assessment generated' },
          },
        ],
      },
    },
  };
});

// Status Reporter – resolves the report scope (a sprint or the whole project) in code, computes
// every number for that scope, and builds the OpenAI request. The model only writes the narrative
// and may cite only task IDs that are in scope (enum-constrained per request).

const cfg = $('Config').first().json;
const kb = $('Knowledge Base').first().json;
const f = kb.facts;
const STATUSES = ['Done', 'In Progress', 'Blocked', 'To Do'];

const SYSTEM_PROMPT = `ROLE
You are the Status Reporter inside Mira, a project intelligence assistant for PMs/TPMs at Nexora. You write the narrative of a weekly status report from task-board facts that have already been computed for you, and you refuse to report when there is no task data.

INPUT
- USER REQUEST: what the PM asked for.
- TASK DATA (optional): <scope> (what the report covers), <facts> (counts and completion already computed), <tasks_in_scope>, and <context> (carried-over, blocked and due-soon tasks, upcoming milestones). If TASK DATA is absent, the only information you have is the USER REQUEST text.

DECISION – choose exactly one status
1. TASK DATA is absent → status "NO_DATA". A sentence like "things are going fine" is not task data. Never produce statuses, counts, percentages or task names.
2. TASK DATA is present → status "REPORT".

RULES FOR A REPORT (hallucination guardrails)
- The counts, completion percentage, task tables and RAG status are rendered by code. Do not restate a number unless it appears in <facts>; never estimate or round progress.
- Only call a task overdue, blocked or due soon if <facts> or its Flags say so. A Done task is never overdue. Never generalise ("all tasks are overdue") – name the tasks.
- Refer to tasks by ID and name exactly as given (e.g. "T007 Shortlist AI use cases"). Never mention a task that is not in TASK DATA.
- headline: one sentence capturing the state of the scope (e.g. what is on track and what needs attention).
- summary: 2–3 sentences for a PM audience.
- highlights: progress worth reporting (done or advancing tasks). Each item cites the task_ids it is about.
- concerns: overdue, blocked or due-soon work and why it matters (link to upcoming milestones where relevant). Each item cites task_ids.
- next_week_focus: the 2–4 most important things to move next, each citing task_ids.
- decisions_needed: escalations or decisions the PM should raise (e.g. unblocking a blocked task). Empty array if none.

RULES FOR NO_DATA
- Set report to null.
- message: one sentence stating that no task data is available, so no status can be reported.
- what_to_provide: the information needed – e.g. task list with statuses, owners, due dates, sprint or reporting period, blockers, and milestones.

OUTPUT
Return JSON matching the provided schema. Unused branch must be null.`;

// The Orchestrator decides this (uses_project_on_file); the regex is the fallback for the standalone step workflows.
const usesTaskBoard = (q) => /task board|task data|tasks|sprint\s*\d|project status|ABCDE|AI Adoption/i.test(q);

const sprintNo = (s) => Number(String(s).replace(/\D/g, ''));
function resolveScope(q, sprint) {
  if (sprint) return { type: 'sprint', sprint: `Sprint ${sprint}` };
  const m = q.match(/sprint\s*(\d+)/i);
  if (m) return { type: 'sprint', sprint: `Sprint ${m[1]}` };
  if (/this sprint|current sprint|weekly/i.test(q)) return { type: 'sprint', sprint: f.current_sprint };
  return { type: 'project', sprint: null };
}

const counts = (ts) => Object.fromEntries(STATUSES.map((s) => [s, ts.filter((t) => t.status === s).length]));
const overdueIds = new Set(f.overdue_tasks.map((t) => t.task_id));
const line = (t) => `${t.task_id} | ${t.task_name} | ${t.status} | ${t.assignee} | ${t.priority} | ${t.sprint} | due ${t.due_date} (${t.days_until_due >= 0 ? `in ${t.days_until_due}d` : `${-t.days_until_due}d late`})${overdueIds.has(t.task_id) ? ' | OVERDUE' : ''} | ${t.description}`;

// Every number the report may contain is computed here.
function buildScope(scope) {
  const inScope = scope.type === 'sprint' ? kb.tasks.filter((t) => t.sprint === scope.sprint) : kb.tasks;
  const c = counts(inScope);
  const carriedOver = scope.type === 'sprint'
    ? kb.tasks.filter((t) => t.status !== 'Done' && sprintNo(t.sprint) < sprintNo(scope.sprint)) : [];
  const ids = new Set(inScope.map((t) => t.task_id));
  const outside = (ts) => ts.filter((t) => !ids.has(t.task_id));
  const context = {
    carried_over: carriedOver,
    blocked_elsewhere: outside(kb.tasks.filter((t) => t.status === 'Blocked')),
    due_soon_elsewhere: outside(kb.tasks.filter((t) => f.due_soon_tasks.some((d) => d.task_id === t.task_id))),
  };
  const allowed = [...new Set([...inScope, ...context.carried_over, ...context.blocked_elsewhere, ...context.due_soon_elsewhere].map((t) => t.task_id))];
  const flagged = (pred) => inScope.filter(pred).map((t) => t.task_id);
  return {
    label: scope.type === 'sprint' ? scope.sprint : 'Whole project',
    type: scope.type,
    sprint: scope.sprint,
    task_ids: inScope.map((t) => t.task_id),
    status_counts: c,
    total: inScope.length,
    completion_pct: inScope.length ? Math.round((c.Done / inScope.length) * 100) : 0,
    overdue_ids: flagged((t) => overdueIds.has(t.task_id)),
    blocked_ids: flagged((t) => t.status === 'Blocked'),
    due_soon_ids: flagged((t) => f.due_soon_tasks.some((d) => d.task_id === t.task_id)),
    context_ids: {
      carried_over: context.carried_over.map((t) => t.task_id),
      blocked_elsewhere: context.blocked_elsewhere.map((t) => t.task_id),
      due_soon_elsewhere: context.due_soon_elsewhere.map((t) => t.task_id),
    },
    allowed_task_ids: allowed,
    found: inScope.length > 0,
  };
}

const flags = (ids) => (ids.length ? `${ids.length} (${ids.join(', ')})` : '0');

function taskDataBlock(s) {
  const byId = new Map(kb.tasks.map((t) => [t.task_id, t]));
  const rows = (ids) => (ids.length ? ids.map((id) => line(byId.get(id))).join('\n') : 'none');
  const ms = f.upcoming_milestones.map((m) => `${m.milestone} (Phase ${m.phase}, due ${m.due_date})`).join('; ') || 'none';
  return `TASK DATA – ${kb.project.name}\n` +
    `<scope>\n${s.label} · as of ${f.as_of_date} (week ${f.current_week} of ${f.total_weeks}, ${f.current_phase}; current sprint ${f.current_sprint})\n</scope>\n` +
    `<facts>\nTasks in scope: ${s.total}\n${STATUSES.map((st) => `${st}: ${s.status_counts[st]}`).join('\n')}\nCompletion: ${s.completion_pct}%\n` +
    `Overdue in scope: ${flags(s.overdue_ids)}\nBlocked in scope: ${flags(s.blocked_ids)}\n` +
    `Due within ${cfg.dueSoonDays} days in scope: ${flags(s.due_soon_ids)}\n</facts>\n` +
    `<tasks_in_scope>\nTask | Name | Status | Assignee | Priority | Sprint | Due | Flags | Description\n${rows(s.task_ids)}\n</tasks_in_scope>\n` +
    `<context>\nCarried over from earlier sprints (not done): \n${rows(s.context_ids.carried_over)}\n` +
    `Blocked outside scope: \n${rows(s.context_ids.blocked_elsewhere)}\n` +
    `Due within ${cfg.dueSoonDays} days outside scope: \n${rows(s.context_ids.due_soon_elsewhere)}\n` +
    `Upcoming milestones (${f.upcoming_window}): ${ms}\n</context>`;
}

function responseFormat(allowedIds) {
  const strings = { type: 'array', items: { type: 'string' } };
  const cited = {
    type: 'array',
    items: {
      type: 'object', additionalProperties: false, required: ['text', 'task_ids'],
      properties: { text: { type: 'string' }, task_ids: { type: 'array', items: { type: 'string', enum: allowedIds } } },
    },
  };
  return {
    type: 'json_schema',
    json_schema: {
      name: 'status_output',
      strict: true,
      schema: {
        type: 'object', additionalProperties: false, required: ['status', 'no_data', 'report'],
        properties: {
          status: { type: 'string', enum: ['REPORT', 'NO_DATA'] },
          no_data: {
            anyOf: [{ type: 'null' }, {
              type: 'object', additionalProperties: false, required: ['message', 'what_to_provide'],
              properties: { message: { type: 'string' }, what_to_provide: strings },
            }],
          },
          report: {
            anyOf: [{ type: 'null' }, {
              type: 'object', additionalProperties: false,
              required: ['headline', 'summary', 'highlights', 'concerns', 'next_week_focus', 'decisions_needed'],
              properties: {
                headline: { type: 'string' }, summary: { type: 'string' },
                highlights: cited, concerns: cited, next_week_focus: cited, decisions_needed: cited,
              },
            }],
          },
        },
      },
    },
  };
}

return $input.all().map(({ json: req }) => {
  const scope = (req.uses_project_on_file ?? usesTaskBoard(req.query)) ? buildScope(resolveScope(req.query, req.sprint)) : null;
  const hasData = Boolean(scope?.found);
  const userContent = `USER REQUEST:\n${req.query}\n\n` +
    (hasData ? taskDataBlock(scope) : 'TASK DATA: none provided.');
  const messages = [
    { role: 'system', content: SYSTEM_PROMPT },
    { role: 'user', content: userContent },
  ];
  return {
    json: {
      ...req,
      agent: 'Status Reporter',
      uses_project_data: hasData,
      scope,
      started_at: new Date().toISOString(),
      openaiRequest: {
        model: cfg.model,
        temperature: Number(cfg.temperature),
        max_tokens: Number(cfg.maxTokens),
        response_format: responseFormat(hasData ? scope.allowed_task_ids : kb.tasks.map((t) => t.task_id)),
        messages,
      },
    },
  };
});

// Status Reporter – parses the model narrative, verifies every task ID and number in it against
// the computed facts, renders the report (counts, tables and RAG come from code), and describes
// the LangSmith trace for this request.

const kb = $('Knowledge Base').first().json;
const cfg = $('Config').first().json;
const requests = $('Status Reporter: Build Prompt').all();
const f = kb.facts;
const STATUSES = ['Done', 'In Progress', 'Blocked', 'To Do'];

const byId = new Map(kb.tasks.map((t) => [t.task_id, t]));
const overdueIds = new Set(f.overdue_tasks.map((t) => t.task_id));
const cell = (s) => String(s ?? '').replace(/\|/g, '/').replace(/\n/g, ' ');
const list = (items) => (items.length ? items.map((x) => `- ${x}`).join('\n') : '- _None._');
const timing = (t) => (t.status === 'Done' ? 'Done'
  : t.status === 'Blocked' ? `⛔ Blocked · due in ${t.days_until_due}d`
  : t.days_until_due < 0 ? `⚠ ${-t.days_until_due}d overdue` : t.days_until_due === 0 ? 'Due today' : `Due in ${t.days_until_due}d`);

// RAG from fixed rules, so the overall status never depends on the model's tone.
function rag(scope) {
  const watched = [...scope.task_ids, ...scope.context_ids.carried_over].map((id) => byId.get(id));
  const overdue = watched.filter((t) => overdueIds.has(t.task_id));
  const blocked = watched.filter((t) => t.status === 'Blocked');
  const reasons = [];
  let level = 'Green';
  const lateHigh = overdue.filter((t) => t.priority === 'High' && -t.days_until_due > 7);
  const blockedSoon = blocked.filter((t) => t.days_until_due <= Number(cfg.dueSoonDays));
  if (lateHigh.length || blockedSoon.length) {
    level = 'Red';
    lateHigh.forEach((t) => reasons.push(`${t.task_id} is high priority and more than 7 days overdue`));
    blockedSoon.forEach((t) => reasons.push(`${t.task_id} is blocked and due within ${cfg.dueSoonDays} days`));
  } else if (overdue.length || blocked.length) {
    level = 'Amber';
    overdue.forEach((t) => reasons.push(`${t.task_id} ${t.task_name} is ${-t.days_until_due}d overdue`));
    blocked.forEach((t) => reasons.push(`${t.task_id} ${t.task_name} is blocked (due ${t.due_date})`));
  } else reasons.push('no overdue or blocked tasks');
  return { level, reasons };
}
const RAG_ICON = { Green: '🟢', Amber: '🟠', Red: '🔴' };

// Numbers the narrative may use: computed counts/percentages, task timings and numbers that
// appear in the source task text (e.g. KPIs "15%", "3 distribution centers").
function allowedNumbers(scope) {
  const nums = new Set([scope.total, f.total_tasks, f.current_week, f.total_weeks,
    ...Object.values(scope.status_counts), ...Object.values(f.status_counts),
    scope.context_ids.carried_over.length, scope.context_ids.blocked_elsewhere.length,
    scope.context_ids.due_soon_elsewhere.length, f.upcoming_milestones.length,
    scope.overdue_ids.length, scope.blocked_ids.length, scope.due_soon_ids.length,
    f.overdue_tasks.length, f.blocked_tasks.length, f.due_soon_tasks.length,
    Number(cfg.dueSoonDays), Number(cfg.upcomingWindowDays)]);
  const pcts = new Set([scope.completion_pct, f.completion_pct]);
  for (const id of scope.allowed_task_ids) {
    const t = byId.get(id);
    nums.add(Math.abs(t.days_until_due));
    for (const m of `${t.task_name} ${t.description}`.matchAll(/(\d+)(%?)/g)) (m[2] ? pcts : nums).add(Number(m[1]));
  }
  for (const m of kb.project.description.matchAll(/(\d+)%/g)) pcts.add(Number(m[1]));
  const dates = new Set([f.as_of_date, ...scope.allowed_task_ids.map((id) => byId.get(id).due_date),
    ...f.upcoming_milestones.map((m) => m.due_date)]);
  return { nums, pcts, dates };
}

// Dates in the narrative ("2026-04-26", "April 26, 2026", "26 April") must be real dates from the data.
const MONTHS = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];
const MONTH = '(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\\.?';
const DATE_PATTERNS = [
  [/\b(\d{4})-(\d{2})-(\d{2})\b/g, (m) => [m[1], m[2], m[3]]],
  [new RegExp(`\\b${MONTH}\\s+(\\d{1,2})(?:st|nd|rd|th)?(?:,?\\s+(\\d{4}))?`, 'gi'), (m) => [m[3], MONTHS.indexOf(m[1].toLowerCase()) + 1, m[2]]],
  [new RegExp(`\\b(\\d{1,2})(?:st|nd|rd|th)?\\s+${MONTH}(?:,?\\s+(\\d{4}))?`, 'gi'), (m) => [m[3], MONTHS.indexOf(m[2].toLowerCase()) + 1, m[1]]],
];
function extractDates(text) {
  const found = [];
  let rest = text;
  for (const [re, parts] of DATE_PATTERNS) {
    rest = rest.replace(re, (...m) => {
      const [y, mo, d] = parts(m);
      found.push({ raw: m[0], iso: `${y ?? f.as_of_date.slice(0, 4)}-${String(mo).padStart(2, '0')}-${String(d).padStart(2, '0')}` });
      return ' ';
    });
  }
  return { found, rest };
}

function groundingCheck(report, scope) {
  const allowed = new Set(scope.allowed_task_ids);
  const { nums, pcts, dates } = allowedNumbers(scope);
  const items = [
    { where: 'headline', text: report.headline, task_ids: [] },
    { where: 'summary', text: report.summary, task_ids: [] },
    ...['highlights', 'concerns', 'next_week_focus', 'decisions_needed']
      .flatMap((k) => report[k].map((x, i) => ({ where: `${k}[${i + 1}]`, ...x }))),
  ];
  const issues = [];
  let grounded = 0;
  for (const it of items) {
    const problems = [];
    const ids = [...new Set([...(it.text.match(/\bT\d{3}\b/g) ?? []), ...it.task_ids])];
    const outOfScope = ids.filter((id) => !allowed.has(id));
    if (outOfScope.length) problems.push(`task not in scope: ${outOfScope.join(', ')}`);
    const { found, rest } = extractDates(it.text);
    found.filter((d) => !dates.has(d.iso)).forEach((d) => problems.push(`unsupported date “${d.raw}”`));
    const stripped = rest.replace(/\bT\d{3}\b/g, ' ').replace(/\b(sprint|phase|week|q)\s*\d+/gi, ' ');
    for (const m of stripped.matchAll(/(\d+(?:\.\d+)?)\s*(%|percent)?/g)) {
      const n = Number(m[1]);
      if (m[2] ? !pcts.has(n) : !nums.has(n)) problems.push(`unsupported ${m[2] ? 'percentage' : 'number'} “${m[0].trim()}”`);
    }
    if (problems.length) issues.push(`${it.where}: ${problems.join(', ')}`);
    else grounded++;
  }
  return { checked: items.length, grounded, score: items.length ? grounded / items.length : 1, issues };
}

function taskTable(ids) {
  return ['| ID | Task | Owner | Priority | Sprint | Due | Timing |', '|---|---|---|---|---|---|---|',
    ...ids.map((id) => byId.get(id)).map((t) =>
      `| ${t.task_id} | ${cell(t.task_name)} | ${t.assignee} | ${t.priority} | ${t.sprint} | ${t.due_date} | ${timing(t)} |`)].join('\n');
}

const citedList = (items) => (items.length
  ? items.map((x) => `- ${x.text}${x.task_ids.length ? ` _(${x.task_ids.join(', ')})_` : ''}`).join('\n')
  : '- _None._');

function renderReport(report, scope, r, grounding) {
  const c = scope.status_counts;
  const progress = ['| Status | Tasks |', '|---|---|', ...STATUSES.map((s) => `| ${s} | ${c[s]} |`), `| **Total** | **${scope.total}** |`].join('\n');
  const byStatus = STATUSES.filter((s) => c[s] > 0).map((s) =>
    `### ${s} (${c[s]})\n\n${taskTable(scope.task_ids.filter((id) => byId.get(id).status === s))}`);
  const ctx = scope.context_ids;
  const context = [
    ctx.carried_over.length ? `**Carried over from earlier sprints (not done)**\n\n${taskTable(ctx.carried_over)}` : null,
    ctx.blocked_elsewhere.length ? `**Blocked outside this scope**\n\n${taskTable(ctx.blocked_elsewhere)}` : null,
    ctx.due_soon_elsewhere.length ? `**Due within ${cfg.dueSoonDays} days outside this scope**\n\n${taskTable(ctx.due_soon_elsewhere)}` : null,
  ].filter(Boolean);
  return [
    `# Weekly Status Report — ${scope.label}`,
    `_Generated by Mira · as of ${f.as_of_date} (week ${f.current_week} of ${f.total_weeks}, ${f.current_phase}) · Source: sample_task_board.csv_`,
    `**Overall status: ${RAG_ICON[r.level]} ${r.level}** — ${r.reasons.join('; ')}`,
    `**${report.headline}**`,
    '## Summary', report.summary,
    '## Progress',
    `${progress}\n\nCompletion: **${scope.completion_pct}%** (${c.Done} of ${scope.total} done)` +
      (scope.type === 'sprint' ? ` · Whole project: ${f.completion_pct}% (${f.status_counts.Done} of ${f.total_tasks} done)` : ''),
    '## Tasks by status', ...byStatus,
    ...(context.length ? ['## Watch list', ...context] : []),
    '## Highlights', citedList(report.highlights),
    '## Concerns & blockers', citedList(report.concerns),
    '## Focus for next week', citedList(report.next_week_focus),
    '## Decisions / escalations needed', citedList(report.decisions_needed),
    '---',
    `Grounding check: ${grounding.grounded}/${grounding.checked} narrative items verified (task IDs in scope, numbers match the task board)` +
      (grounding.issues.length ? `\n${grounding.issues.map((i) => `- ⚠ ${i}`).join('\n')}` : ' ✅'),
  ].join('\n\n');
}

function renderNoData(nd, req) {
  const notFound = req.scope && !req.scope.found ? `${req.scope.label} has no tasks on the task board. ` : '';
  return [
    '## No task data available',
    `${notFound}I can't produce a status report from the request alone – there are no task statuses, owners or due dates to report on.`,
    nd.message,
    '**To generate the report, please provide**', list(nd.what_to_provide),
    '_No task statuses, counts or progress percentages were generated._',
  ].join('\n\n');
}

return $input.all().map((item, i) => {
  const req = requests[i].json;
  const body = item.json.body ?? item.json;
  const headers = item.json.headers ?? {};
  const finishedAt = new Date().toISOString();
  const content = body.choices?.[0]?.message?.content ?? '';

  let output = null, parseError = null;
  try { output = JSON.parse(content); } catch (e) { parseError = e.message; }

  let markdown, grounding = null, r = null;
  const status = output?.status ?? 'ERROR';
  const scope = req.scope;
  if (!output) {
    markdown = `⚠ Status Reporter returned unparseable output (${parseError}).\n\n${content}`;
  } else if (status === 'REPORT' && output.report && scope?.found) {
    grounding = groundingCheck(output.report, scope);
    r = rag(scope);
    markdown = renderReport(output.report, scope, r, grounding);
  } else {
    markdown = renderNoData(output.no_data ?? { message: 'No task data was provided.', what_to_provide: [] }, req);
  }

  // Model latency from OpenAI's header gives accurate per-call timing even when items run in sequence.
  const latencyMs = Number(headers['openai-processing-ms']) || (Date.parse(finishedAt) - Date.parse(req.started_at));
  const llmEnd = new Date(Date.parse(req.started_at) + latencyMs).toISOString();
  const usage = body.usage ?? {};
  const counts = grounding ? STATUSES.map((s) => `${s} ${scope.status_counts[s]}`).join(' · ') : null;

  return {
    json: {
      test_id: req.test_id,
      query: req.query,
      checks: req.checks,
      agent: req.agent,
      status,
      uses_project_data: req.uses_project_data,
      scope: grounding ? scope.label : null,
      counts,
      rag: r?.level ?? null,
      grounding,
      markdown,
      usage: { input_tokens: usage.prompt_tokens ?? 0, output_tokens: usage.completion_tokens ?? 0, total_tokens: usage.total_tokens ?? 0 },
      trace: {
        name: 'Mira',
        start_time: req.started_at,
        end_time: finishedAt,
        inputs: { query: req.query },
        outputs: { status, response: markdown },
        tags: ['mira', 'status', req.test_id].filter(Boolean),
        metadata: { test_id: req.test_id, agent: req.agent, status, scope: scope?.label ?? null, uses_project_data: req.uses_project_data, groundedness: grounding?.score ?? null, as_of_date: f.as_of_date },
        children: [
          {
            name: req.agent,
            run_type: 'llm',
            start_time: req.started_at,
            end_time: llmEnd,
            inputs: { messages: req.openaiRequest.messages },
            outputs: body,
            model: req.openaiRequest.model,
            temperature: req.openaiRequest.temperature,
          },
          {
            name: 'Grounding Check',
            run_type: 'chain',
            start_time: llmEnd,
            end_time: finishedAt,
            inputs: { status, scope: scope?.label ?? null },
            outputs: grounding ? { ...grounding, rag: r, counts } : { skipped: 'no report generated' },
          },
        ],
      },
    },
  };
});
